import { describe, expect, it, vi } from 'vitest';
import { PROFILE_STORAGE_KEY, readProfile, writeProfile, upsertSession, togglePlanItem, summarizeProfile, type ProfileSession } from './profile';

function session(id: string, score = 60, overrides: Partial<ProfileSession> = {}): ProfileSession {
    return {
        id, completedAt: `2026-10-${id.padStart(2, '0')}T12:00:00.000Z`, scenarioId: 'interview', difficulty: 'neutral', completedPlanItems: [],
        report: {
            summary: 'An evidenced practice report.', strengths: ['Clear introduction', 'Relevant example'], improvements: ['Add numbers', 'Explain the outcome'], suggestedResponse: 'I reduced the queue by 20%.',
            assessment: {
                skills: ['structure', 'specificity', 'relevance', 'reflection'].map(skill => ({ skill, score, evidence: 'I owned the queue.', advice: 'Quantify the result.' })) as NonNullable<ProfileSession['report']['assessment']>['skills'],
                observations: [{ skill: 'specificity', kind: 'improvement', title: 'Add measurable results', evidence: 'I owned the queue.', action: 'Name the measured change.' }],
                plan: [{ skill: 'specificity', title: 'Quantify a result', exercise: 'Rewrite one example with a number.', successCriteria: 'One outcome includes a measured result.' }]
            }
        }, ...overrides
    };
}
const stored = (sessions: ProfileSession[]) => ({ getItem: () => JSON.stringify({ version: 1, sessions }) });

describe('profile persistence', () => {
    it('reads an empty store and round-trips valid reports', () => {
        expect(readProfile({ getItem: () => null })).toEqual([]);
        const setItem = vi.fn();
        writeProfile({ setItem }, [session('1')]);
        expect(setItem).toHaveBeenCalledWith(PROFILE_STORAGE_KEY, expect.any(String));
        expect(readProfile({ getItem: () => setItem.mock.calls[0][1] })).toEqual([session('1')]);
    });
    it.each(['{', '{}', '{"version":2,"sessions":[]}', '{"version":1,"sessions":[{}]}'])('rejects corrupt or unsupported data: %s', raw => {
        expect(() => readProfile({ getItem: () => raw })).toThrow(/saved profile/i);
    });
    it('rejects invalid scores, dates and unavailable storage without overwriting', () => {
        expect(() => readProfile(stored([session('1', 101)]))).toThrow(/saved profile/i);
        expect(() => readProfile(stored([session('1', 50, { completedAt: 'not-a-date' })]))).toThrow(/saved profile/i);
        expect(() => readProfile({ getItem: () => { throw new Error('denied'); } })).toThrow(/read.*profile/i);
        const setItem = vi.fn();
        expect(() => writeProfile({ setItem }, [session('1', -1)])).toThrow(/profile/i);
        expect(setItem).not.toHaveBeenCalled();
        expect(() => writeProfile({ setItem: () => { throw new Error('quota'); } }, [session('1')])).toThrow(/save.*profile/i);
    });
    it('rejects duplicate persisted ids and unknown completed plan items', () => {
        expect(() => readProfile(stored([session('1'), session('1')]))).toThrow(/saved profile/i);
        expect(() => readProfile(stored([session('1', 60, { completedPlanItems: ['not-a-plan'] })]))).toThrow(/saved profile/i);
    });
    it('preserves legacy reports and optional live-feedback connector data', () => {
        const { assessment: _assessment, ...report } = session('1').report;
        expect(readProfile(stored([session('1', 60, { report })]))[0].report.assessment).toBeUndefined();
        const next = session('2', 70, { liveFeedback: [{ id: 'signal', occurredAt: '2026-10-02T11:59:00.000Z', skill: 'structure', kind: 'strength', evidence: 'A clear opening.' }] });
        expect(readProfile(stored([next]))).toEqual([next]);
    });
});

describe('profile updates', () => {
    it('deduplicates by id without mutating input', () => {
        const original = [session('1'), session('2')];
        const next = upsertSession(original, session('1', 80));
        expect(next).toHaveLength(2);
        expect(next.find(item => item.id === '1')?.report.assessment?.skills[0].score).toBe(80);
        expect(original[0].report.assessment?.skills[0].score).toBe(60);
        expect(upsertSession(original, session('3'))).toHaveLength(3);
    });
    it('toggles only an actual plan item without mutating sessions', () => {
        const original = [session('1')];
        const itemId = 'specificity:Quantify a result';
        const next = togglePlanItem(original, '1', itemId);
        expect(next[0].completedPlanItems).toEqual([itemId]);
        expect(original[0].completedPlanItems).toEqual([]);
        expect(togglePlanItem(next, '1', itemId)[0].completedPlanItems).toEqual([]);
        expect(() => togglePlanItem(original, '1', 'unknown')).toThrow(/plan/i);
        expect(() => togglePlanItem(original, 'missing', itemId)).toThrow(/session/i);
    });
});

describe('profile summaries', () => {
    it('sorts and compares only the selected scenario and difficulty', () => {
        const original = [session('3', 80), session('2', 95, { difficulty: 'challenging' }), session('1', 60), session('4', 90, { scenarioId: 'raise' })];
        const summary = summarizeProfile(original, 'interview', 'neutral');
        expect(summary.sessions.map(item => item.id)).toEqual(['1', '3']);
        expect(summary.latest?.id).toBe('3');
        expect(summary.score).toBe(80);
        expect(summary.delta).toBe(20);
        expect(original[0].id).toBe('3');
        expect(summarizeProfile([session('1', 80), session('2', 65)], 'interview', 'neutral').delta).toBe(-15);
    });
    it('does not invent evidence for empty or legacy sessions', () => {
        expect(summarizeProfile([], 'interview', 'neutral')).toMatchObject({ score: null, delta: null, patterns: [] });
        const { assessment: _assessment, ...report } = session('1').report;
        expect(summarizeProfile([session('1', 60, { report })], 'interview', 'neutral')).toMatchObject({ score: null, delta: null, patterns: [] });
        expect(summarizeProfile([session('1', 60, { report }), session('2', 75)], 'interview', 'neutral').delta).toBeNull();
    });
    it('counts skill and kind once per session and only surfaces patterns still present', () => {
        const first = session('1');
        first.report.assessment!.observations = [...first.report.assessment!.observations, ...first.report.assessment!.observations];
        const second = session('2');
        const summary = summarizeProfile([first, second], 'interview', 'neutral');
        expect(summary.patterns).toEqual([{ skill: 'specificity', kind: 'improvement', count: 2, total: 2, latest: second.report.assessment!.observations[0] }]);
        expect(summarizeProfile([first], 'interview', 'neutral').patterns).toEqual([]);
        const third = session('3');
        third.report.assessment!.observations = [{ skill: 'structure', kind: 'strength', title: 'Clear opening', evidence: 'First, I set a goal.', action: 'Keep this approach.' }];
        expect(summarizeProfile([first, second, third], 'interview', 'neutral').patterns).toEqual([]);
        expect(summarizeProfile([third, { ...third, id: '4', completedAt: '2026-10-04T12:00:00.000Z' }], 'interview', 'neutral').patterns[0]).toMatchObject({ kind: 'strength', count: 2 });
    });
});
EOF
